const { email, firstName, lastName, phone, company, jobTitle, lifecycleStage, customProperties } = $.input;
if (!email) throw new Error('email is required');
const properties = { email };
if (firstName) properties.firstname = firstName;
if (lastName) properties.lastname = lastName;
if (phone) properties.phone = phone;
if (company) properties.company = company;
if (jobTitle) properties.jobtitle = jobTitle;
if (lifecycleStage) properties.lifecyclestage = lifecycleStage;
if (customProperties) Object.assign(properties, customProperties);
return { properties };

const resp = $.steps.createContact.response || {};
return {
  contactId: resp.id || '',
  properties: resp.properties || {},
  createdAt: resp.createdAt || '',
  created: !!resp.id,
  summary: resp.id
    ? `Created contact ${resp.properties?.email || $.input.email} (ID: ${resp.id})`
    : 'Failed to create contact'
};
